patch_bare.authz.py:
def _has_admin_role(user):
    return user["role"] == "admin"


def _owner_permits(user, resource):
    owner = resource.get("owner")
    return owner is None or owner == user["id"]


def is_authorized(user, resource):
    """Return True if `user` may read `resource`."""
    checks = (_has_admin_role(user), _owner_permits(user, resource))
    for allowed in checks:
        if allowed:
            return True
    return False
